const api = async (url:string, options?:RequestInit) => { const response = await fetch(url, { credentials:"include", headers: { "Content-Type":"application/json", ...(options?.headers ?? {}) }, ...options }); if (!response.ok) throw new Error((await response.json().catch(()=>null))?.error ?? "Request failed"); return response.status === 204 ? null : response.json(); };
const getParam = (key:string, fallback:string) => new URLSearchParams(location.search).get(key) ?? fallback;
const setParams = (next:Record<string,string | undefined>) => { const query = new URLSearchParams(location.search); Object.entries(next).forEach(([key,value]) => value ? query.set(key,value) : query.delete(key)); history.pushState({}, "", `${location.pathname}?${query}`); window.dispatchEvent(new PopStateEvent("popstate")); };
type Theme = "auto" | "light" | "dark";
const themeKey = "gre-theme";
const readTheme = (): Theme => { try { const value = localStorage.getItem(themeKey); return value === "light" || value === "dark" || value === "auto" ? value : "auto"; } catch { return "auto"; } };
const nextTheme = (theme: Theme): Theme => theme === "auto" ? "light" : theme === "light" ? "dark" : "auto";
